import{_ as l,a0 as s,w as i,s as p,I as a,x as e,a1 as n,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"充分利用你的下一次技術會議的 7 個技巧 | LCTT x X-CMD","titleTemplate":false,"description":"充分利用你的下一次技術會議的 7 個技巧 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"充分利用你的下一次技術會議的 7 個技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"充分利用你的下一次技術會議的 7 個技巧 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230411.3 ⭐️⭐️ 7 tips to make the most of your next tech conference","title":"充分利用你的下一次技術會議的 7 個技巧","tag":"202304","desc":""},"relativePath":"202304/20230411.3 ⭐️⭐️ 7 tips to make the most of your next tech conference.md","filePath":"[post].md"}'),m={name:"202304/20230411.3 ⭐️⭐️ 7 tips to make the most of your next tech conference.md"};function f(h,t,u,x,b,T){const r=s("Link");return i(),p("div",null,[t[20]||(t[20]=a("h1",{id:"充分利用你的下一次技術會議的-7-個技巧",tabindex:"-1"},[e("充分利用你的下一次技術會議的 7 個技巧 "),a("a",{class:"header-anchor",href:"#充分利用你的下一次技術會議的-7-個技巧","aria-label":"Permalink to “充分利用你的下一次技術會議的 7 個技巧”"},"​")],-1)),t[21]||(t[21]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202304/27/074139chzhgld44l4dih4b.jpg",alt:""})],-1)),t[22]||(t[22]=a("blockquote",null,[a("p",null,"會議是科技行業的福利之一。以下是如何充分利用你所參加的會議的方法。")],-1)),a("p",null,[t[2]||(t[2]=e("我在 2023 年 2 月參加了兩個針對開源軟件的技術會議。我是比利時根特舉辦的 ",-1)),n(r,{href:"https://cfgmgmtcamp.eu/ghent2023/"},{default:o(()=>[...t[0]||(t[0]=[e("Config Management Camp",-1)])]),_:1}),t[3]||(t[3]=e(" 的演講者，也是比利時布魯塞爾 ",-1)),n(r,{href:"https://fosdem.org/2023/"},{default:o(()=>[...t[1]||(t[1]=[e("FOSDEM",-1)])]),_:1}),t[4]||(t[4]=e(" 的與會者。本文旨在着重講述我在會議上的經驗，併為你提供一些如何充分利用這種機會的建議。",-1))]),t[23]||(t[23]=d('<h3 id="保持目的性" tabindex="-1">保持目的性 <a class="header-anchor" href="#保持目的性" aria-label="Permalink to “保持目的性”">​</a></h3><p>不同的人蔘加會議有不同的原因。有些人是某個主題、知識或興趣領域的演講者。另外一些人是希望從這些講座中獲得知識並與其他志同道合的人建立聯繫的與會者。也有一些代表他們公司的與會者。你很可能屬於其中的一類。明確你希望從會議中獲得什麼，這是進行一次成功會議訪問的第一步。如果你是一個演講者，這意味着你要熟練掌握你所演講的東西。如果你是一個與會者，你應該對你想從會議中獲得什麼有一個認識。</p><h3 id="瞭解場地和會議日程" tabindex="-1">瞭解場地和會議日程 <a class="header-anchor" href="#瞭解場地和會議日程" aria-label="Permalink to “瞭解場地和會議日程”">​</a></h3><p>FOSDEM 是一個非常大的會議，在兩天的時間裏至少有六千人蔘加。對於一個參加這樣一個大型的會議的與會者來説，由於許多演講會在同一時間舉行，無法參加所有你感興趣的會議並不奇怪。通常，這樣的大型會議在大學或會議中心等寬敞的場地舉行。由於面積非常大，會議會根據特定的主題分散在整個會場。這些會議會有一個固定的日程，所以有時你可能必須迅速地從場地的一邊跑到另一邊。場館地圖可以在場館網站上輕鬆獲取。在第一天早點到達會場並熟悉它是非常有用的。這有助於節省你在一個演講結束時匆忙趕往另一個演講的時間。</p><h3 id="記些筆記" tabindex="-1">記些筆記 <a class="header-anchor" href="#記些筆記" aria-label="Permalink to “記些筆記”">​</a></h3><p>在現場集中注意力和專注於演講當然很好。然而，你的頭腦只能記住這麼多。當然，有些人會試着儘可能地利用他們的手機拍攝正在演示的幻燈片（順着演講者的演講節奏）。如果你想在社交媒體上快速更新你正在參加的會議信息，這是很好的。但是它不是很有效的筆記。通常幻燈片上的有效信息是最少的。但是如果演講者在台上深入地解釋了一些東西，你可能會錯過這些解釋。我建議你隨身攜帶一個記事本和一支筆。你甚至可以帶上筆記本電腦做筆記。這個做法的目的是在於通過在演講中對有趣的花絮做一個簡短的筆記，以便你可以在以後重温它們。而且它讓你總是能在演講快結束時回想起要向演講者提問的問題。</p><h3 id="建立關係和促成協作" tabindex="-1">建立關係和促成協作 <a class="header-anchor" href="#建立關係和促成協作" aria-label="Permalink to “建立關係和促成協作”">​</a></h3><p>會議可能是與志同道合的人彼此交往的最佳場所。他們和你一樣對同樣的話題感興趣。最好利用這段時間來了解在感興趣的話題上正在發生什麼，看看人們如何解決令人感興趣的問題，他們如何處理事情，並掌握整個行業的脈搏。你在會議上的時間有限，所以一定要把你介紹給那些從事與你有關的工作的人。這是一個收集信息的好機會，以便以後與他們溝通。你可以通過電子郵件、Mastodon、領英等方式交換個人信息。</p><h3 id="騰出時間看展位和禮品" tabindex="-1">騰出時間看展位和禮品 <a class="header-anchor" href="#騰出時間看展位和禮品" aria-label="Permalink to “騰出時間看展位和禮品”">​</a></h3><p>大多數技術會議都有來自各種公司或上游項目的展位，希望推銷他們的產品和服務。為了吸引更多參展的人，展位上經常會有各種各樣的免費的禮品（在大多數情況下）。這些禮品通常是貼紙、涼水瓶、有趣的小玩意、毛絨玩具、筆之類。一定要把它們收集起來，這樣你就有東西送給你的同事和朋友了。參觀展位不應該只是為了禮品。你應該利用這個機會與來自不同公司的人交談（即使他們是競爭對手），以瞭解他們能提供什麼。誰沒準你就會得到以後的項目知識！</p><h3 id="放鬆" tabindex="-1">放鬆 <a class="header-anchor" href="#放鬆" aria-label="Permalink to “放鬆”">​</a></h3><p>參加會議不應該只是為了工作。這也讓你你從平時忙碌的日程中休息一下，放鬆一下。很有可能你正在前往一個你還沒有訪問過的不同的國家或城市。會議、會談和技術討論都很重要。但這只是整個體驗的一部分。另一半的經驗是旅行，它可以使人瞭解另一個國家、它的文化、它的人民、食物、語言和不同的生活方式。退一步講，享受所有這些經歷，留下終生的回憶。我建議你在住宿的地方找一些著名的地標兼做。你也應該嘗試當地的美食，或者你可以和當地人聊天。最後，你會發現你認為從來沒有存在過的自己的另一面。</p><h3 id="寫下你的經歷" tabindex="-1">寫下你的經歷 <a class="header-anchor" href="#寫下你的經歷" aria-label="Permalink to “寫下你的經歷”">​</a></h3><p>一旦你從會議回來，不要只是忘記它然後回到你的日常生活，就好像什麼都沒發生一樣。利用這個機會寫下你的經歷，並分享你認為最好的演講以及原因。會議和旅行的主要收穫是什麼？你應該記錄你學到的東西。你應該主動聯繫你在會議上遇到的人。你也可以在社交媒體上關注你可能錯過的事情。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>會議是科技行業的福利之一。我建議每個人在職業生涯中的某個時候都去一次。我希望這篇文章能幫助你瞭解如何在參加技術會議時最大限度地利用會議。</p><p><em>（題圖：MJ/conference illustration talk meetup in high resolution, very detailed, 8k）</em></p><hr>',18)),a("p",null,[t[6]||(t[6]=e("via: ",-1)),n(r,{href:"https://opensource.com/article/23/4/tips-tech-conference"},{default:o(()=>[...t[5]||(t[5]=[e("https://opensource.com/article/23/4/tips-tech-conference",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=e("作者：",-1)),n(r,{href:"https://opensource.com/users/gkamathe"},{default:o(()=>[...t[7]||(t[7]=[e("Gaurav Kamathe",-1)])]),_:1}),t[12]||(t[12]=e(" 選題：",-1)),n(r,{href:"https://github.com/lkxed/"},{default:o(()=>[...t[8]||(t[8]=[e("lkxed",-1)])]),_:1}),t[13]||(t[13]=e(" 譯者：",-1)),n(r,{href:"https://github.com/TaivasJumala"},{default:o(()=>[...t[9]||(t[9]=[e("Taivas Jumala",-1)])]),_:1}),t[14]||(t[14]=e(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[17]||(t[17]=e("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[15]||(t[15]=[e("LCTT",-1)])]),_:1}),t[18]||(t[18]=e(" 原創編譯，",-1)),n(r,{href:"https://linux.cn/"},{default:o(()=>[...t[16]||(t[16]=[e("Linux中國",-1)])]),_:1}),t[19]||(t[19]=e(" 榮譽推出",-1))])])}const P=l(m,[["render",f]]);export{C as __pageData,P as default};
